import pathlib,subprocess,os,json,time,hashlib
R=pathlib.Path.cwd(); H=R/'audit/SOL-035'; roots=('src','scripts','specs','tests','audit','handoff')
def snap(): return {p.relative_to(R).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for d in roots for p in (R/d).rglob('*') if p.is_file()}
env={k:v for k,v in os.environ.items() if k.upper()!='PYTHONPATH'}; env['PYTHONDONTWRITEBYTECODE']='1'; before=snap(); t=time.time(); argv=[os.sys.executable,'-B','audit/SOL-035/verify.py','--check']; r=subprocess.run(argv,env=env,capture_output=True); after=snap(); (H/'final-check.stdout.txt').write_bytes(r.stdout); (H/'final-check.stderr.txt').write_bytes(r.stderr); record=dict(argv=argv,exit_code=r.returncode,runtime_seconds=time.time()-t,PYTHONPATH_keys=[k for k in env if k.upper()=='PYTHONPATH'],before=before,after=after,unchanged=before==after,stdout='final-check.stdout.txt',stderr='final-check.stderr.txt'); record['result']=json.loads(r.stdout) if r.returncode==0 else None; (H/'final-check.json').write_text(json.dumps(record,indent=2,sort_keys=True)+'\n',encoding='utf8',newline='\n'); assert r.returncode==0 and before==after
